namespace sv_b3c413df3aa142eb9eb6a8db38c3efcb.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "WH-A";

    public string SelectedWarehouseName =>
        Warehouses.TryGetValue(SelectedWarehouseId, out var name) ? name : SelectedWarehouseId;

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["WH-A"] = "Warehouse A — Main Distribution",
        ["WH-B"] = "Warehouse B — East Regional",
        ["WH-C"] = "Warehouse C — West Regional",
        ["WH-D"] = "Warehouse D — Cold Storage",
    };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_b3c413df3aa142eb9eb6a8db38c3efcb.Services;

public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    /// <summary>Simulates a database query for low-stock items.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Starts polling if not already running. Multiple callers share the same poll loop.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;
        if (_cts is not null) return; // already running

        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    /// <summary>
    /// Decrements subscriber count; stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = null;
            _timer?.Dispose();
            _timer = null;
        }
    }

    /// <summary>
    /// Restarts polling with a new warehouse id (called when the warehouse changes).
    /// </summary>
    public void RestartPolling(string warehouseId)
    {
        if (_cts is null) return; // not currently polling
        var subs = _subscriberCount;
        // Force-stop regardless of subscriber count
        _cts.Cancel();
        _cts.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
        _subscriberCount = 0;

        // Restart with the saved subscriber count
        _subscriberCount = subs;
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        // Fetch immediately on start
        await FetchAndNotifyAsync(warehouseId);

        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await _timer.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync(warehouseId);
            }
        }
        catch (OperationCanceledException) { /* expected on stop */ }
    }

    private async Task FetchAndNotifyAsync(string warehouseId)
    {
        LowStockCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

