                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LowStockCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum level
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Recent Activity</div>
            <div class="card-body">
                <ul class="list-group list-group-flush">
                    <li class="list-group-item d-flex justify-content-between">
                        <span>Inbound shipment received</span>
                        <span class="text-muted">2 min ago</span>
                    </li>
                    <li class="list-group-item d-flex justify-content-between">
                        <span>Pick list #4021 completed</span>
                        <span class="text-muted">8 min ago</span>
                    </li>
                    <li class="list-group-item d-flex justify-content-between">
                        <span>Cycle count scheduled</span>
                        <span class="text-muted">15 min ago</span>
                    </li>
                </ul>
            </div>
        </div>
    </div>
</div>

