@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.LowStockCount > 5 ? "border-danger" : "border-warning")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LowStockCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum level
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Recent Activity</div>
            <div class="card-body">
                <ul class="list-group list-group-flush">
                    <li class="list-group-item d-flex justify-content-between">
                        <span>Inbound shipment received</span>
                        <span class="text-muted">2 min ago</span>
                    </li>
                    <li class="list-group-item d-flex justify-content-between">
                        <span>Pick list #4021 completed</span>
                        <span class="text-muted">8 min ago</span>
                    </li>
                    <li class="list-group-item d-flex justify-content-between">
                        <span>Cycle count scheduled</span>
                        <span class="text-muted">15 min ago</span>
                    </li>
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        // Subscribe to warehouse changes
        _warehouseHandler = () => InvokeAsync(() =>
        {
            AlertService.RestartPolling(WarehouseState.SelectedWarehouseId);
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        // Subscribe to alert updates
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _alertHandler;

        // Start polling for the current warehouse
        AlertService.StartPolling(WarehouseState.SelectedWarehouseId);
    }

    public void Dispose()
    {
        AlertService.StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnChange -= _alertHandler;
    }
}

